/**
 * Custom Worker entry. OpenNext builds the Next.js app into `.open-next/worker.js`; this module
 * serves it through `fetch`, mounts the MCP server (packages/mcp) at `/mcp` ahead of Next.js, and adds
 * the cron handler for the onboarding job queue and the Builder League scheduled work. Crons are
 * declared in wrangler.jsonc (`triggers.crons`).
 */
// eslint-disable-next-line @typescript-eslint/ban-ts-comment
// @ts-ignore `.open-next/worker.js` is generated by `opennextjs-cloudflare build`.
import { default as openNextHandler } from "./.open-next/worker.js";
import type { ExecutionContext, ScheduledController } from "@cloudflare/workers-types";
import { createDb } from "./lib/db";
import { runOnboardingCron } from "./lib/onboarding/runner";
import { BUILDER_LEAGUE_CRON, runBuilderLeagueCron } from "./lib/builder-league/cron";
import type { RenderBucket } from "./lib/builder-league/render-jobs";
import { serveMcp, type McpWorkerEnv } from "./lib/mcp-worker-mount";

interface ScheduledEnv {
  DB: D1Database;
  ONBOARDING_V2_ENABLED?: string;
  BUILDER_EVIDENCE?: RenderBucket;
}

type NextFetch = (request: Request, env: McpWorkerEnv, ctx: ExecutionContext) => Promise<Response>;
const nextFetch = openNextHandler.fetch as NextFetch;

const worker = {
  async fetch(request: Request, env: McpWorkerEnv, ctx: ExecutionContext): Promise<Response> {
    const mcpResponse = await serveMcp(request, env, (inner) => nextFetch(inner, env, ctx));
    return mcpResponse ?? nextFetch(request, env, ctx);
  },

  async scheduled(controller: ScheduledController, env: ScheduledEnv, ctx: ExecutionContext): Promise<void> {
    ctx.waitUntil(
      runOnboardingCron(createDb(env.DB), controller.cron, {
        enabled: env.ONBOARDING_V2_ENABLED === "true",
        polar: async () => (await import("./lib/polar")).polar,
      }).catch(() => {
        console.error(`onboarding cron "${controller.cron}" failed`);
      })
    );
    // Runs whatever BUILDER_LEAGUE_ENABLED says: finalizing snapshots, year reviews and render-job
    // expiry only write league-private tables, and the pages gate visibility on the flag. Skipping them
    // while the flag is off would leave pilot data unfinalized and render outputs past retention.
    if (controller.cron === BUILDER_LEAGUE_CRON) {
      ctx.waitUntil(
        runBuilderLeagueCron(env, controller.cron).catch(() => {
          console.error(`builder league cron "${controller.cron}" failed`);
        })
      );
    }
  },
};

export default worker;
